script:
$match = {{ItemName}}
$keys = @(
  'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
  'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run',
  'HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
)
$removed = @()
foreach ($key in $keys) {
  if (-not (Test-Path $key)) { continue }
  $item = Get-ItemProperty -Path $key
  foreach ($property in $item.PSObject.Properties) {
    if ($property.Name -like 'PS*') { continue }
    if ($property.Name -like ('*' + $match + '*')) {
      $removed += @{ Key = $key; Name = $property.Name; Value = $property.Value }
      Remove-ItemProperty -Path $key -Name $property.Name -ErrorAction SilentlyContinue
    }
  }
}
$removed | ConvertTo-Json | Set-Content -Path {{BackupFile}} -Encoding UTF8
Write-Output ('已移除 ' + $removed.Count + ' 个匹配的开机启动项（原值已备份）。')

$services = 'wuauserv','bits','cryptsvc'
foreach ($name in $services) { Stop-Service -Name $name -Force -ErrorAction SilentlyContinue }
$source = Join-Path $env:SystemRoot 'SoftwareDistribution'
$newName = 'SoftwareDistribution.old.' + (Get-Date -Format 'yyyyMMddHHmmss')
if (Test-Path $source) { Rename-Item -Path $source -NewName $newName -ErrorAction SilentlyContinue }
foreach ($name in $services) { Start-Service -Name $name -ErrorAction SilentlyContinue }
Write-Output ('已重置系统更新组件；原目录已重命名为 ' + $newName)

$folder = Join-Path $env:SystemRoot 'System32'
foreach ($name in 'jscript.dll','vbscript.dll','mshtml.dll') {
  $file = Join-Path $folder $name
  if (Test-Path $file) { regsvr32 /s $file }
}
Write-Output '已重新注册系统脚本组件（jscript / vbscript / mshtml）。'

$drive = {{Drive}}
Enable-ComputerRestore -Drive $drive -ErrorAction Stop
Write-Output ('已为 ' + $drive + ' 启用系统还原。')
